🔍 诊断工具 . class ConvergenceDiagnostics: """收敛性诊断工具""" def __init__(self): self.diagnostic_rules = self._build_diagnostic_rules() def _build_diagnostic_rules(self) -&gt; List[Dict]: """构建诊断规则""" return [ { 'name': 'slow_convergence', 'condition': lambda metrics: metrics['convergence_rate'] &lt; 1e-5, 'diagnosis': '收敛速度过慢', 'causes': ['学习率过小', '梯度消失', '优化器选择不当'], 'solutions': ['增加学习率', '使用梯度裁剪', '尝试不同优化器'] }, { 'name': 'unstable_training', 'condition': lambda metrics: metrics['stability_index'] &lt; 0.3, 'diagnosis': '训练不稳定', 'causes': ['学习率过大', '批次大小不当', '数据噪声'], 'solutions': ['降低学习率', '调整批次大小', '数据预处理'] }, { 'name': 'gradient_explosion', 'condition': lambda metrics: metrics['gradient_norm'] &gt; 100, 'diagnosis': '梯度爆炸', 'causes': ['学习率过大', '网络初始化不当', '数据尺度问题'], 'solutions': ['梯度裁剪', '降低学习率', '重新初始化'] }, { 'name': 'gradient_vanishing', 'condition': lambda metrics: metrics['gradient_norm'] &lt; 1e-6, 'diagnosis': '梯度消失', 'causes': ['网络过深', '激活函数选择', '权重初始化'], 'solutions': ['残差连接', '更换激活函数', '改进初始化'] } ] def diagnose(self, metrics: Dict[str, float]) -&gt; List[Dict]: """执行诊断""" diagnoses = [] for rule in self.diagnostic_rules: try: if rule['condition'](metrics): diagnoses.append({ 'name': rule['name'], 'diagnosis': rule['diagnosis'], 'causes': rule['causes'], 'solutions': rule['solutions'], 'severity': self._assess_severity(rule['name'], metrics) }) except Exception as e: continue return diagnoses def _assess_severity(self, rule_name: str, metrics: Dict[str, float]) -&gt; str: """评估严重程度""" if rule_name == 'gradient_explosion': return 'critical' if metrics.get('gradient_norm', 0) &gt; 1000 else 'high' elif rule_name == 'unstable_training': stability = metrics.get('stability_index', 1.0) if stability &lt; 0.1: return 'high' elif stability &lt; 0.3: return 'medium' else: return 'low' elif rule_name == 'slow_convergence': rate = metrics.get('convergence_rate', 0) if rate &lt; 1e-7: return 'high' elif rate &lt; 1e-5: return 'medium' else: return 'low' else: return 'medium' def generate_diagnostic_report(self, monitor: ConvergenceMonitor) -&gt; str: """生成诊断报告""" metrics = monitor.metrics.get_convergence_summary() diagnoses = self.diagnose(metrics) report = "# 收敛性诊断报告

" # 当前状态 report += "## 当前状态

" report += f"- 收敛速率: {metrics.get('convergence_rate', 0):.2e}
" report += f"- 稳定性指数: {metrics.get('stability_index', 0):.4f}
" report += f"- 梯度范数: {metrics.get('gradient_norm', 0):.2e}
" report += f"- 当前损失: {metrics.get('current_loss', 0):.6f}
" confidence = monitor.metrics.compute_convergence_confidence() report += f"- 收敛置信度: {confidence:.2%}

" # 诊断结果 if diagnoses: report += "## 诊断结果

" for diag in diagnoses: report += f"### {diag['diagnosis']} ({diag['severity'].upper()})

" report += "**可能原因:**
" for cause in diag['causes']: report += f"- {cause}
" report += "
**建议解决方案:**
" for solution in diag['solutions']: report += f"- {solution}
" report += "
" else: report += "## 诊断结果

✅ 未发现明显问题

" # 警告和建议 status_report = monitor.get_status_report() if status_report['alerts']: report += "## 当前警告

" for alert in status_report['alerts']: report += f"- **{alert['type'].upper()}**: {alert['message']}
" report += "
" if status_report['recommendations']: report += "## 优化建议

" for rec in status_report['recommendations']: priority_emoji = {'high': '🔴', 'medium': '🟡', 'low': '🟢'} emoji = priority_emoji.get(rec['priority'], '⚪') report += f"{emoji} **{rec['type']}**: {rec['reason']}
" report += "
" return report .
